const TROPICAL_SIGNS = ['Aries', 'Taurus', 'Gemini', 'Cancer', 'Leo', 'Virgo', 'Libra', 'Scorpio', 'Sagittarius', 'Capricorn', 'Aquarius', 'Pisces'];
const SKY_INDEX = (() => {
  const idx = {};
  for (const row of SKY_DATA.split(';')) {
    const [k, mc, sc, mt, st, ml, sl, mb] = row.split('|');
    if (!k) continue;
    const id = (k[0] === 'f' ? 'full' : 'new') + '-moon-' + k.slice(1, 5) + '-' + k.slice(5, 7) + '-' + k.slice(7, 9);
    idx[id] = { mc, sc, mt, st, ml: +ml, sl: +sl, mb: +mb };
  }
  return idx;
})();
/* Returns the separate data fields for one event. Never guesses: anything
   not in the verified table is returned with verified:false. */
function skyPositions(eventId) {
  const r = SKY_INDEX[eventId];
  const body = (code, sign, lon, lat) => {
    const verified = !!(r && code && CONSTELLATION_NAMES[code]);
    return {
      verified,
      constellation: verified ? CONSTELLATION_NAMES[code] : null,      // SBA display (true sky)
      constellationCode: verified ? code : null,
      tropicalSign: verified && sign !== '' ? TROPICAL_SIGNS[+sign] : null, // comparison only
      eclipticLongitude: r && isFinite(lon) ? lon : null,
      eclipticLatitude: r && lat != null && isFinite(lat) ? lat : null
    };
  };
  return {
    system: SKY_SYSTEM,
    inTable: !!r,
    moon: body(r && r.mc, r && r.mt, r && r.ml, r && r.mb),
    sun: body(r && r.sc, r && r.st, r && r.sl, null)
  };
}
const PENDING_TEXT = 'Position pending verification';
const placeName = b => (b && b.verified ? b.constellation : null);
function placementLine(sky) {
  const m = placeName(sky.moon), s = placeName(sky.sun);
  if (!m && !s) return 'Moon & Sun · ' + PENDING_TEXT.toLowerCase();
  return (m ? `Moon in ${m}` : 'Moon position pending verification') + ' · ' + (s ? `Sun in ${s}` : 'Sun position pending verification');
}
